def add(kind,n,page,note,parts,domain,rep='text'):
 direct=sorted({d for p in parts for d in p.get('assessed_8227_demand_ids',[])})
 components=sorted(({POWER,MODEL,MENS}|{d for p in parts for d in p.get('component_demand_ids',[])})-set(direct))
 source_models=[p['source_quantity_model']for p in parts if 'source_quantity_model'in p]
 r=h.add(kind,n,page,note,parts,direct,components,powers=source_models)
 r.update(representation=rep,mapping_rationale='First identify which quantity is fixed and which is optimised. Closed/open faces,positive lengths,and perimeter/volume constraints determine different objective functions before calculus. A stationary inputvalue and a stationary quantityvalue are different requested outputs;unasked dimensions remain working.',physical_parameter_domain=domain)
 r['value_level_scope_decisions'][0].update(quoted_value='; '.join(source_models),reason='All derivative exponents in these source models are rational. Physical-domain restrictions are recorded separately rather than using positivity as a substitute for a source value.')
 for p in parts:p['given_representation']=rep
 return r
def value(label,expr,key,kp,direct,method,units=None):
 p=v(label,expr,key,kp,method);p.update(assessed_8227_demand_ids=direct)
 if units:p.update(units=units,printed_key_units=units)
 return p
def model(label,expr,key,kp,method):
 p=value(label,expr,key,kp,[],method);p.update(component_demand_ids=[MODEL,MENS],check_mode='show/prove',response_format='proof/show-that',source_quantity_model=key);return p
def nature(label,result,method,kp,expr,key):
 p=reasoning(label,result,method,kp,'show/prove'if 'show'in label or'verification'in label else'matches');p.update(assessed_8227_demand_ids=[NATURE],component_demand_ids=[POWER]);extra(p,'nature-check',expr,key);return p
def rounded(label,expr,key,kp,method):
 p=value(label,expr,key,kp,[POINT],method);p['operation']={'kind':'rounded','operands':[expr],'decimal_places':1};p['exact_canonical_answer']=expr;return p

